"""de — faith_b."""

T = {
"faith_071": ("Was bedeutet der Name Allahs «As-Salam»?", ["Der Friede, frei von jedem Mangel", "Der Schöpfer", "Der Versorger", "Der Mächtige"], "As-Salam gehört zu den am Ende der Sure Al-Haschr genannten Namen: Er ist der Friede, frei von jeder Unvollkommenheit."),
"faith_072": ("Welche Eigenschaften stellt Vers 59:22 neben den Namen Allahs, gleich nach «kein Gott außer Ihm»?", ["Kenner des Verborgenen und des Offenkundigen, der Allerbarmer", "Der König und der Krieger", "Der Reiche und der Großzügige", "Der Starke und der Schnelle"], "«Er ist Allah, außer dem es keinen Gott gibt, der Kenner des Verborgenen und des Offenkundigen. Er ist der Allerbarmer, der Barmherzige»."),
"faith_073": ("Was gebietet der Koran mit den schönsten Namen Allahs zu tun?", ["Ihn mit ihnen anzurufen", "Sie nur zu zählen", "Sie an die Türen zu schreiben", "Über sie zu schweigen"], "«Allah gehören die schönsten Namen: so ruft Ihn mit ihnen an»."),
"faith_074": ("Wie stellt die Sure Ta-Ha die Namen Allahs dar?", ["«Allah! Es gibt keinen Gott außer Ihm. Sein sind die schönsten Namen»", "«Seine Namen sind verborgen»", "«Seine Namen sind unzählbar»", "«Seine Namen sind neun»"], "«Allah! Es gibt keinen Gott außer Ihm. Sein sind die schönsten Namen»."),
"faith_075": ("Welche Formel gebraucht der Koran, um jede Ähnlichkeit mit Allah auszuschließen?", ["«Nichts ist Ihm gleich; und Er ist der Allhörende, der Allsehende»", "«Er ist der größte der Könige»", "«Er ist wie das Licht»", "«Niemand sieht Ihn»"], "«Nichts ist Ihm gleich; und Er ist der Allhörende, der Allsehende»."),
"faith_076": ("Was sagt der Thronvers über Schlummer und Schlaf?", ["Weder Schlummer noch Schlaf überkommen Ihn", "Er schläft nachts", "Er ruht am siebten Tag", "Er wacht jeden zweiten Tag"], "«Ihn überkommt weder Schlummer noch Schlaf»."),
"faith_077": ("Was sagt der Koran über Allahs Wissen um das fallende Blatt?", ["Kein Blatt fällt, ohne dass Er es weiß", "Er erfährt es danach", "Die Engel sagen es Ihm", "Es wird nicht aufgeschrieben"], "«Und bei Ihm sind die Schlüssel des Verborgenen… kein Blatt fällt, ohne dass Er es weiß»."),
"faith_078": ("Wem ist Allah laut Sure Qaf näher als der Mensch?", ["Als seiner Halsschlagader", "Als seinem Schatten", "Als seiner Stimme", "Als seinem Haus"], "«Und Wir haben den Menschen erschaffen und wissen, was seine Seele ihm einflüstert; und Wir sind ihm näher als seine Halsschlagader»."),
"faith_079": ("Wie beschreibt der Koran die mit dem Feuer betrauten Engel?", ["Sie widersetzen sich Allah nicht und tun, was ihnen befohlen wird", "Einige zögern", "Sie schlafen", "Sie wählen"], "«…Engel, streng und hart, die sich Allah nicht widersetzen in dem, was Er ihnen befiehlt, und die tun, was ihnen befohlen wird»."),
"faith_080": ("Wie beschreibt der Koran die Engel gegenüber dem Wort Allahs?", ["Sie kommen Ihm im Reden nicht zuvor und handeln auf Seinen Befehl", "Sie streiten über Seine Befehle", "Sie entscheiden allein", "Sie schweigen immer"], "«Vielmehr sind sie geehrte Diener: sie kommen Ihm im Reden nicht zuvor und handeln auf Seinen Befehl»."),
"faith_081": ("Welchen Engel nennt der Koran als denjenigen, der die Offenbarung auf das Herz des Propheten ﷺ herabbrachte?", ["Jibril (Gabriel)", "Mika'il (Michael)", "Israfil", "Malik"], "«Sag: Wer Jibril feind ist… er ist es, der ihn mit Allahs Erlaubnis auf dein Herz herabgebracht hat»."),
"faith_082": ("Welcher andere Engel wird neben Jibril in der Sure Al-Baqara genannt?", ["Mikal (Michael)", "Israfil", "Ridwan", "Munkar"], "«Wer Allah, Seinen Engeln, Seinen Gesandten, Jibril und Mikal feind ist…»"),
"faith_083": ("Welche Glaubensgegenstände zählt Vers 4:136 auf?", ["Allah, Seinen Gesandten, das offenbarte Buch und die früheren Bücher", "Nur das Buch", "Nur die Propheten", "Nur die Engel"], "«O die ihr glaubt! Glaubt an Allah und Seinen Gesandten und das Buch, das Er auf Seinen Gesandten herabgesandt hat, und die Schrift, die Er zuvor herabgesandt hat»."),
"faith_084": ("Welches Buch erwähnt der Koran als Dawud gegeben?", ["Den Zabur (die Psalmen)", "Die Tora", "Das Evangelium", "Die Blätter Ibrahims"], "«…und Dawud gaben Wir den Zabur»."),
"faith_085": ("Welche Sure trägt den Namen der Dschinn, die den Koran hörten und glaubten?", ["Al-Jinn", "Al-Insan", "An-Nas", "Al-Furqan"], "«Sag: Mir ist offenbart worden, dass eine Gruppe von Dschinn zuhörte und dann sagte: Wir haben einen wunderbaren Vortrag gehört»."),
"faith_086": ("Wozu wurden Dschinn und Menschen laut Sure Adh-Dhariyat erschaffen?", ["Damit sie Ihm dienen", "Um die Erde zu bevölkern", "Um zu bauen", "Um zu streiten"], "«Und Ich habe die Dschinn und die Menschen nur dazu erschaffen, dass sie Mir dienen»."),
"faith_087": ("Was sagt der Koran über jede Seele und den Tod?", ["Jede Seele wird den Tod kosten", "Manche Seelen sterben nicht", "Der Tod ist ein Zweifel", "Der Tod ist ein endloser Schlaf"], "«Jede Seele wird den Tod kosten, und erst am Tag der Auferstehung wird euch euer Lohn voll erstattet»."),
"faith_088": ("In welchem Zustand werden die Menschen laut Sure Az-Zalzala hervorkommen, damit ihnen ihre Werke gezeigt werden?", ["In getrennten Gruppen", "Alle zusammen in einer Reihe", "Schlafend", "Schweigend und unsichtbar"], "«An jenem Tag werden die Menschen in getrennten Gruppen hervorkommen, damit ihnen ihre Werke gezeigt werden»."),
"faith_089": ("Wie beschreibt die Sure Al-Kahf das Verzeichnis der Werke am Jüngsten Tag?", ["Es lässt nichts aus, weder Kleines noch Großes, ohne es zu erfassen", "Es verzeichnet nur Großes", "Es wird gelöscht", "Es wird von Menschen geschrieben"], "«Sie werden sagen: “Wehe uns! Was ist mit diesem Buch, das nichts auslässt, weder Kleines noch Großes, ohne es zu erfassen?”»"),
"faith_090": ("Was sagt der Koran über die Glieder am Tag des Gerichts?", ["Die Hände werden sprechen und die Füße Zeugnis ablegen", "Sie werden stumm bleiben", "Sie werden verborgen sein", "Sie werden verwandelt"], "«Heute versiegeln Wir ihre Münder, und ihre Hände werden zu Uns sprechen und ihre Füße Zeugnis ablegen über das, was sie erworben haben»."),
"faith_091": ("Wie kennzeichnet der Koran das Gebet hinsichtlich seiner Zeit?", ["Eine Vorschrift zu festgesetzten Zeiten", "Frei zu jeder Stunde", "Einmal in der Woche", "Nur nachts"], "«Gewiss, das Gebet ist den Gläubigen zu festgesetzten Zeiten vorgeschrieben»."),
"faith_092": ("Wovor bewahrt das Gebet laut Sure Al-'Ankabut?", ["Vor dem Schändlichen und dem Verwerflichen", "Vor dem Hunger", "Vor der Krankheit", "Vor der Reise"], "«Und verrichte das Gebet: das Gebet hält vom Schändlichen und vom Verwerflichen ab»."),
"faith_093": ("Welches Gebet hebt der Koran besonders als «das mittlere Gebet» hervor?", ["Es wird genannt, ohne bestimmt zu werden, im Gebot, die Gebete zu wahren", "Nur das Morgengebet", "Nur das Abendgebet", "Das Freitagsgebet"], "«Haltet die Gebete ein und das mittlere Gebet, und steht demütig vor Allah»."),
"faith_094": ("Zu welchem Zweck gebietet der Koran in der Sure Ta-Ha das Gebet?", ["Zum Gedenken Allahs", "Zum Ausruhen", "Zum Versammeln", "Zum Zählen der Stunden"], "«Ich bin Allah: es gibt keinen Gott außer Mir. So diene Mir und verrichte das Gebet zu Meinem Gedenken»."),
"faith_095": ("Welche Eigenschaft des Gebets eröffnet in Al-Mu'minun die Liste der erfolgreichen Gläubigen?", ["Die Demut (Khuschu') im Gebet", "Die Länge", "Die Schnelligkeit", "Die Anzahl"], "«Den Gläubigen wird es wohl ergehen: denjenigen, die in ihrem Gebet demütig sind»."),
"faith_096": ("Welches Gebet beschreibt die Sure Al-Isra als «bezeugt» (maschhuda)?", ["Die Rezitation der Morgendämmerung", "Das Abendgebet", "Das Mittagsgebet", "Das Freitagsgebet"], "«Verrichte das Gebet vom Neigen der Sonne bis zum Dunkel der Nacht, und die Rezitation der Morgendämmerung: die Rezitation der Morgendämmerung wird ja bezeugt»."),
"faith_097": ("Mit welchen beiden Dingen gebietet der Koran, Hilfe zu suchen?", ["Mit Geduld und Gebet", "Mit Kraft und Reichtum", "Mit Reise und Ruhe", "Mit Schweigen und Einsamkeit"], "«O die ihr glaubt! Sucht Hilfe in der Geduld und im Gebet: Allah ist mit den Geduldigen»."),
"faith_098": ("Wie viele Rak'as hat das Pflichtgebet des Dhuhr?", ["Vier", "Zwei", "Drei", "Fünf"], "Dhuhr, 'Asr und 'Ischa haben je vier Pflicht-Rak'as; darin stimmen die Rechtsschulen überein."),
"faith_099": ("Welches ist das letzte der fünf täglichen Pflichtgebete?", ["Al-'Ischa", "Al-Fajr", "Al-Maghrib", "Al-'Asr"], "Die Reihenfolge ist: Fajr, Dhuhr, 'Asr, Maghrib, 'Ischa."),
"faith_100": ("Wie heißt die Haltung der Niederwerfung im Gebet?", ["Der Sujud", "Der Ruku'", "Der Qiyam", "Der Taschahhud"], "Qiyam ist das Stehen, Ruku' die Verbeugung, Sujud die Niederwerfung und Taschahhud das Sitzen des Zeugnisses."),
"faith_101": ("Was sieht der Koran für den Kranken oder den Reisenden im Ramadan vor?", ["Eine gleiche Anzahl anderer Tage nachzuholen", "Gar nichts", "Eine doppelte Pflicht", "Ein immerwährendes Fasten"], "«Wer von euch krank ist oder sich auf einer Reise befindet, der faste eine gleiche Anzahl anderer Tage»."),
"faith_102": ("Welches Ziel gibt der Koran dem vorgeschriebenen Fasten?", ["Die Gottesfurcht (Taqwa) zu erlangen", "Abzunehmen", "Zu sparen", "Auszuruhen"], "«Euch ist das Fasten vorgeschrieben, so wie es denen vor euch vorgeschrieben war, auf dass ihr gottesfürchtig werdet»."),
"faith_103": ("Was antwortet Allah inmitten der Fastenverse dem, der nach Seiner Nähe fragt?", ["«Ich bin nahe: Ich erhöre den Ruf des Rufenden»", "«Wartet die Nacht ab»", "«Fragt die Engel»", "«Sucht in der Ferne»"], "«Und wenn dich Meine Diener nach Mir fragen, so bin Ich nahe: Ich erhöre den Ruf des Rufenden, wenn er Mich anruft»."),
"faith_104": ("Wie viele Empfängergruppen der Zakat zählt der Koran auf?", ["Acht", "Drei", "Fünf", "Zwölf"], "«Die Almosen sind nur für die Armen, die Bedürftigen, die damit Beschäftigten, diejenigen, deren Herzen gewonnen werden sollen, für die Freilassung von Gefangenen, die Verschuldeten, auf Allahs Weg und für den Reisenden»."),
"faith_105": ("Welche Wirkung schreibt der Koran der aus dem Vermögen genommenen Zakat zu?", ["Sie reinigt und lässt wachsen", "Sie macht arm", "Sie ist symbolisch", "Sie ersetzt das Gebet"], "«Nimm von ihrem Besitz ein Almosen, mit dem du sie reinigst und läuterst»."),
"faith_106": ("Welche beiden Pflichten verbindet der Koran am häufigsten miteinander?", ["Das Gebet und die Zakat", "Das Fasten und die Reise", "Die Pilgerfahrt und den Handel", "Das Lesen und das Schreiben"], "«Und verrichtet das Gebet und entrichtet die Zakat; was ihr für euch selbst an Gutem vorausschickt, das werdet ihr bei Allah finden»."),
"faith_107": ("Was erreicht Allah laut Koran beim Opfer?", ["Weder das Fleisch noch das Blut, sondern die Gottesfurcht des Gläubigen", "Nur das Fleisch", "Nur das Blut", "Die Zahl der Tiere"], "«Weder ihr Fleisch noch ihr Blut erreicht Allah, aber Ihn erreicht die Gottesfurcht von euch»."),
"faith_108": ("Was ist die beste Wegzehrung für die Pilgerfahrt, laut Koran?", ["Die Gottesfurcht", "Das Gold", "Die Vorräte", "Die Reittiere"], "«Und versorgt euch mit Wegzehrung; doch die beste Wegzehrung ist die Gottesfurcht»."),
"faith_109": ("Welchen Ritus erwähnt der Koran um das Alte Haus?", ["Den Umlauf (Tawaf)", "Das Laufen in der Wüste", "Das Besteigen eines Hügels", "Das Fasten dort"], "«…und sie sollen den Umlauf um das Alte Haus vollziehen»."),
"faith_110": ("Wo gebietet der Koran, Allahs zu gedenken, nachdem man von 'Arafat aufgebrochen ist?", ["Bei al-Mash'ar al-Haram, in Muzdalifa", "Am Berg Uhud", "In Quba", "In Ta'if"], "«Wenn ihr dann von 'Arafat herbeiströmt, so gedenkt Allahs bei al-Mash'ar al-Haram»."),
"faith_111": ("Welche Art von Reue verlangt der Koran von den Gläubigen?", ["Eine aufrichtige Reue (Tawba nasuh)", "Eine schriftliche Reue", "Eine öffentliche Reue", "Eine jährliche Reue"], "«O die ihr glaubt! Wendet euch Allah zu in aufrichtiger Reue»."),
"faith_112": ("Was sagt die Sure Asch-Schura über die Annahme der Reue?", ["Er ist es, der die Reue Seiner Diener annimmt und die Missetaten verzeiht", "Reue wird nicht angenommen", "Es braucht einen Vermittler", "Man muss ein Jahr warten"], "«Und Er ist es, der die Reue von Seinen Dienern annimmt und die Missetaten verzeiht, und Er weiß, was ihr tut»."),
"faith_113": ("Was tun jene, die der Koran lobt, nachdem sie eine Verfehlung begangen haben?", ["Sie gedenken Allahs und bitten um Vergebung", "Sie fliehen", "Sie schweigen", "Sie beschuldigen andere"], "«Und diejenigen, die, wenn sie etwas Schändliches getan oder sich selbst Unrecht zugefügt haben, Allahs gedenken und um Vergebung für ihre Sünden bitten»."),
"faith_114": ("Wie oft gebietet der Koran in der Sure Al-Ahzab, Allahs zu gedenken?", ["Viel, morgens und abends", "Einmal im Jahr", "Einmal in der Woche", "Nur auf Reisen"], "«O die ihr glaubt! Gedenkt Allahs in häufigem Gedenken, und preist Ihn morgens und abends»."),
"faith_115": ("Worüber denken «die Verständigen» am Ende der Sure Al 'Imran nach?", ["Über die Erschaffung der Himmel und der Erde, in jeder Haltung", "Über die Ernten", "Über die Karawanen", "Über die Abstammungen"], "«Diejenigen, die Allahs stehend, sitzend und auf der Seite liegend gedenken und über die Erschaffung der Himmel und der Erde nachdenken»."),
"faith_116": ("Was gebietet der Koran zu tun, nachdem ein Entschluss gefasst ist?", ["Auf Allah zu vertrauen", "Ein Zeichen abzuwarten", "Einen Wahrsager zu fragen", "Aufzugeben"], "«Und wenn du dich entschlossen hast, dann verlasse dich auf Allah: Allah liebt die auf Ihn Vertrauenden»."),
"faith_117": ("Auf wen richtet die Sure Asch-Scharh das Verlangen, sobald die Aufgabe getan ist?", ["Auf seinen Herrn", "Auf die Ruhe", "Auf die Familie", "Auf die Menschen"], "«Wenn du frei bist, dann mühe dich ab; und nach deinem Herrn richte dein Verlangen»."),
"faith_118": ("Womit vergleicht die Sure Al-Hadid das Leben dieser Welt?", ["Mit einem Regen, dessen Pflanzenwuchs gefällt, dann vergilbt und zu Spreu wird", "Mit einer langen Reise", "Mit einem Berg", "Mit einem Ozean"], "«Wisst, dass das diesseitige Leben nur Spiel und Zerstreuung ist… wie ein Regen, dessen Pflanzenwuchs den Bauern gefällt; dann trocknet er, und du siehst ihn gelb werden, hierauf wird er zu Spreu»."),
"faith_119": ("Was erklärt der Koran für besser als Besitz und Kinder, den Schmuck dieser Welt?", ["Die bleibenden guten Werke", "Das Gold", "Den Ruhm", "Das Land"], "«Besitz und Söhne sind der Schmuck des diesseitigen Lebens, aber die bleibenden guten Werke sind bei deinem Herrn besser an Belohnung»."),
"faith_120": ("Welche Frage stellt der Koran über den Zweck der Erschaffung des Menschen?", ["«Meintet ihr denn, dass Wir euch zwecklos erschaffen hätten?»", "«Wer hat euch benannt?»", "«Wohin werdet ihr gehen?»", "«Wie viele seid ihr?»"], "«Meintet ihr denn, dass Wir euch zwecklos erschaffen hätten und dass ihr nicht zu Uns zurückgebracht würdet?»"),
"faith_121": ("Welches Versprechen gibt der Koran dem, der Allahs gedenkt?", ["«Gedenkt Meiner, so gedenke Ich eurer»", "«Ihr werdet reich sein»", "«Ihr werdet lange leben»", "«Ihr werdet reisen»"], "«So gedenkt Meiner, so gedenke Ich eurer. Und dankt Mir und seid Mir gegenüber nicht undankbar»."),
"faith_122": ("An wen gebietet der Koran, Streitfragen zu verweisen?", ["An Allah und den Gesandten ﷺ", "An die Ältesten", "An den Markt", "An die Dichter"], "«Und wenn ihr über etwas streitet, dann bringt es vor Allah und den Gesandten, wenn ihr an Allah und den Jüngsten Tag glaubt»."),
"faith_123": ("Wie beschreibt die Sure Al-Anfal die Herzen der Gläubigen beim Gedenken Allahs?", ["Ihre Herzen erbeben, und ihr Glaube nimmt bei der Rezitation zu", "Sie verhärten sich", "Sie schlafen ein", "Sie vergessen"], "«Die Gläubigen sind nur diejenigen, deren Herzen sich ängstigen, wenn Allahs gedacht wird, und die, wenn ihnen Seine Verse verlesen werden, dadurch an Glauben zunehmen»."),
"faith_124": ("Was gebietet der Koran gänzlich dem Herrn der Weltenbewohner zu widmen?", ["Das Gebet, die Andachtshandlungen, das Leben und das Sterben", "Den Handel", "Die Ernten", "Die Reisen"], "«Sag: Gewiss, mein Gebet, meine Andachtshandlungen, mein Leben und mein Sterben gehören Allah, dem Herrn der Weltenbewohner»."),
"faith_125": ("Welche Bedingung stellt die Sure Al-Bayyina an den gebotenen Dienst?", ["Allah aufrichtig und ausschließlich zu dienen", "Öffentlich zu dienen", "Schriftlich zu dienen", "Nur in der Gruppe zu dienen"], "«Und ihnen wurde nur befohlen, Allah zu dienen und dabei Ihm gegenüber aufrichtig in der Religion zu sein, das Gebet zu verrichten und die Zakat zu entrichten»."),
"faith_126": ("Was beschreibt der Koran als fließend in den den Gottesfürchtigen versprochenen Gärten?", ["Bäche", "Straßen", "Brücken", "Brunnen"], "Der Koran beschreibt wiederholt die Gärten, «durcheilt von Bächen»."),
"faith_127": ("Was sagt der Koran über das, was den Gläubigen als Lohn verborgen ist?", ["Keine Seele weiß, welche Freude der Augen für sie bereitgehalten wird", "Alles ist genau beschrieben", "Es sind Reichtümer", "Es sind Königreiche"], "«Keine Seele weiß, welche Freude der Augen für sie verborgen gehalten wird als Lohn für das, was sie zu tun pflegten»."),
"faith_128": ("Was verspricht der Koran denen, die Gutes tun, über den besten Lohn hinaus?", ["Eine Mehrung (Ziyada)", "Einen Aufschub", "Ein Königreich", "Ein Buch"], "«Für diejenigen, die Gutes tun, gibt es das Beste und noch mehr»."),
"faith_129": ("Wie beschreibt der Koran den Empfang der Gottesfürchtigen am Eingang des Paradieses?", ["«Friede sei mit euch! Ihr wart gut: so tretet ein, ewig darin zu bleiben»", "In Schweigen", "Nach einem langen Prozess", "Einzeln ohne ein Wort"], "«Und seine Wärter sagen zu ihnen: “Friede sei mit euch! Ihr wart gut: so tretet ein, ewig darin zu bleiben”»."),
"faith_130": ("Wozu gebietet der Koran in der Sure Al 'Imran zu eilen?", ["Zu einer Vergebung des Herrn und einem Paradies so weit wie Himmel und Erde", "Zum Markt", "Zur Reise", "Zum Reichtum"], "«Und eilt zu Vergebung von eurem Herrn und zu einem Garten, dessen Breite Himmel und Erde umfasst, bereitet für die Gottesfürchtigen»."),
"faith_131": ("Welche Verantwortung legt der Koran dem Gläubigen gegenüber seiner Familie auf?", ["Sie und sich selbst vor einem Feuer zu bewahren", "Sie reich zu machen", "Ihnen Sprachen beizubringen", "Sie auf Reisen zu nehmen"], "«O die ihr glaubt! Bewahrt euch selbst und eure Angehörigen vor einem Feuer, dessen Brennstoff Menschen und Steine sind»."),
"faith_132": ("Wie bestimmt Vers 2:177 die wahre Frömmigkeit (al-birr)?", ["An Allah, den Jüngsten Tag, die Engel, das Buch und die Propheten zu glauben und vom Besitz zu geben", "Das Gesicht nach Osten oder Westen zu wenden", "Nur zu fasten", "Zu reisen"], "«Frömmigkeit besteht nicht darin, dass ihr eure Gesichter gegen Osten oder Westen wendet, sondern fromm ist, wer an Allah, den Jüngsten Tag, die Engel, das Buch und die Propheten glaubt»."),
"faith_133": ("Wer wird die vollbrachten Werke sehen, laut Sure At-Tawba?", ["Allah, Sein Gesandter ﷺ und die Gläubigen", "Niemand", "Nur die Engel", "Die Könige"], "«Und sag: Handelt! Allah wird euer Tun sehen, und auch Sein Gesandter und die Gläubigen»."),
"faith_134": ("Mit welcher Aussage endet die Sure Al-Ikhlas?", ["«Und niemand ist Ihm gleich»", "«Er ist der Größte»", "«Er ist nahe»", "«Er ist der Erste»"], "«Und niemand ist Ihm gleich»."),
"faith_135": ("Welche vier Namen vereint die Sure Al-Hadid in einem einzigen Vers?", ["Der Erste, der Letzte, der Offenbare und der Verborgene", "Der König, der Heilige, der Friede, der Getreue", "Der Schöpfer, der Erschaffer, der Gestalter, der Weise", "Der Lebendige, der Beständige, der Hörende, der Sehende"], "«Er ist der Erste und der Letzte, der Offenbare und der Verborgene, und Er weiß über alles Bescheid»."),
"faith_136": ("Welche Namen zählt das Ende der Sure Al-Haschr nach «dem Herrscher» auf?", ["Der Heilige, der Friede, der Sicherheit Gebende, der Wächter", "Der Schöpfer, der Gestalter", "Der Vergebende, der Barmherzige", "Der Hörende, der Sehende"], "«Er ist Allah, der Herrscher, der Heilige, der Friede, der Sicherheit Gebende, der Wächter, der Allmächtige»."),
"faith_137": ("Wie heißt die Formel «Es gibt keinen Gott außer Allah, Muhammad ist Sein Gesandter»?", ["Die Schahada (das Glaubensbekenntnis)", "Die Basmala", "Die Takbira", "Die Tasmiya"], "Die Schahada ist das erste Wort des Islam und die erste seiner Säulen."),
"faith_138": ("Wie heißt die Formel «Allahu akbar»?", ["Der Takbir", "Der Tahlil", "Der Tasbih", "Der Tahmid"], "Takbir ist «Allahu akbar», Tasbih «subhan Allah», Tahmid «al-hamdu lillah» und Tahlil «la ilaha illa-llah»."),
"faith_139": ("Wie heißt die Formel «Im Namen Allahs, des Allerbarmers, des Barmherzigen»?", ["Die Basmala", "Die Hamdala", "Die Hawqala", "Der Istirja'"], "Die Basmala eröffnet alle Suren bis auf eine; die Hawqala ist «la hawla wa la quwwata illa billah»."),
"faith_140": ("Welche Worte lehrt der Koran zu sagen, wenn ein Unglück eintritt?", ["«Wir gehören Allah, und zu Ihm kehren wir zurück»", "«Warum ich?»", "«Es wird vorübergehen»", "«Das ist das Los der Menschen»"], "«Diejenigen, die, wenn sie ein Unglück trifft, sagen: “Wir gehören Allah, und zu Ihm kehren wir zurück”»."),
"faith_141": ("Was gebietet der Koran zu sagen, wenn man ankündigt, morgen etwas zu tun?", ["«So Allah will» (in scha' Allah)", "«Es ist versprochen»", "«Ganz gewiss»", "«Ich schwöre es»"], "«Und sag ja nur nicht von einer Sache: “Ich werde dies morgen tun”, ohne hinzuzufügen: “So Allah will”»."),
"faith_142": ("Welches Wissen behält der Koran am Ende der Sure Luqman allein Allah vor?", ["Die Stunde, den Regen, was in den Mutterleibern ist, was man morgen erwirbt und wo man stirbt", "Die Zahl der Sterne", "Die Namen der Könige", "Die Zählung der Tage"], "«Gewiss, Allah besitzt das Wissen über die Stunde, Er lässt den Regen herabkommen und weiß, was in den Mutterleibern ist. Und keine Seele weiß, was sie morgen erwerben wird, noch weiß eine Seele, in welchem Land sie sterben wird»."),
"faith_143": ("Was sagt der Koran über die für jede Gemeinschaft festgesetzte Frist?", ["Wenn sie kommt, wird sie weder um eine Stunde verzögert noch vorverlegt", "Sie ist veränderbar", "Allah kennt sie nicht", "Sie hängt von den Königen ab"], "«Jede Gemeinschaft hat eine Frist: wenn nun ihre Frist kommt, können sie sie weder um eine Stunde hinausschieben noch vorverlegen»."),
"faith_144": ("Was verspricht der Koran jedem, der Gutes tut, Mann oder Frau, als Gläubiger?", ["Ein gutes Leben und einen Lohn nach dem Besten seiner Werke", "Reichtum", "Macht", "Ruhm"], "«Wer rechtschaffen handelt, sei es Mann oder Frau, und dabei gläubig ist, dem werden Wir ganz gewiss ein gutes Leben gewähren»."),
"faith_145": ("Welchen Unterschied macht der Koran in der Sure Al-Hujurat zwischen «Islam» und «Glaube»?", ["Zu sagen «wir haben uns ergeben» ist noch nicht, dass der Glaube in die Herzen eingetreten ist", "Es sind dieselben Worte", "Der Glaube geht immer voran", "Der Islam ist nur für Gelehrte"], "«Die Beduinen sagen: “Wir glauben.” Sag: “Ihr glaubt nicht; sagt vielmehr: Wir haben uns ergeben, denn der Glaube ist noch nicht in eure Herzen eingetreten”»."),
"faith_146": ("Welche Regel nennt die Sure Al-Ma'ida über das Leben eines einzelnen Menschen?", ["Wer einen Menschen tötet, ist als hätte er alle Menschen getötet; wer einen rettet, als hätte er alle gerettet", "Jedes Leben zählt einfach", "Nur Verwandte zählen", "Nur die Zahl zählt"], "«Wer ein Leben tötet, es sei denn für ein anderes Leben oder wegen Unheilstiftung auf der Erde, so ist es, als hätte er alle Menschen getötet; und wer es am Leben erhält, so ist es, als hätte er alle Menschen am Leben erhalten»."),
"faith_147": ("Um wie viel vervielfacht der Koran den Lohn der guten Tat?", ["Um das Zehnfache", "Um das Zweifache", "Um das Hundertfache", "Er wird nicht vervielfacht"], "«Wer mit einer guten Tat kommt, für den gibt es zehnmal soviel; und wer mit einer schlechten Tat kommt, dem wird nur gleichviel vergolten»."),
"faith_148": ("Wie beschreibt die Sure Fatir das Verhältnis der Menschen zu Allah?", ["Sie sind die Armen, und Allah ist der Unbedürftige, der Lobenswürdige", "Sie sind Seine Teilhaber", "Sie sind unabhängig", "Sie sind Seine Gläubiger"], "«O ihr Menschen! Ihr seid es, die Allahs bedürfen, und Allah ist der Unbedürftige, der Lobenswürdige»."),
"faith_149": ("Welche vier Eigenschaften retten laut Sure Al-'Asr vor dem Verlust?", ["Der Glaube, die guten Werke, das Ermahnen zur Wahrheit und zur Geduld", "Reichtum, Kraft, Schönheit, List", "Schweigen, Schlaf, Abgeschiedenheit, Fasten", "Reise, Handel, Schrift, Lesung"], "«Bei der Zeit! Der Mensch ist wahrlich im Verlust, außer denjenigen, die glauben, rechtschaffene Werke tun, einander die Wahrheit und die Geduld nahelegen»."),
"faith_150": ("Woran erklären die Gläubigen im vorletzten Vers der Sure Al-Baqara zu glauben?", ["An Allah, Seine Engel, Seine Bücher und Seine Gesandten", "An ein einziges Buch", "An einen einzigen Engel", "An ihre Vorfahren"], "«Der Gesandte glaubt an das, was zu ihm von seinem Herrn herabgesandt worden ist, und ebenso die Gläubigen: alle glauben an Allah, Seine Engel, Seine Bücher und Seine Gesandten»."),
}
